import { useState, useEffect, useCallback, Key } from "react";

import { DocumentLookupResult, IComponent, StudioProApi } from "@mendix/extensions-api";

import { createDocumentEditorComponent } from "../utils/componentLoader";

import { Model, Provider } from "../../types/model/model";
import { createNewModel } from "../../utils/modelUtils";
import { handleProviderChange } from "./modelHandlers";
import { updateModelDocument } from "../../utils/modelUtils";

import { mendixIconGreyBase64 } from "../../icons/modelIcons";
import { PageContainer, ContentColumnSmall, PageContent } from "../components/PageContainers";
import AppThemeProvider from "../components/AppThemeProvider";
import FormDivider from "../components/FormDivider"
import ComboBoxWithIcon from "../components/ComboBoxWithIcon";
import MxCloudGenAI from "./providers/mxCloudGenAI";

const initialModel: Model = createNewModel()

interface AppProps {
    studioPro: StudioProApi;
    documentId: string;
}

const App: React.FC<AppProps> = ({ studioPro, documentId }) => {
    const messageBoxApi = studioPro.ui.messageBoxes;
    const documentApi = studioPro.app.model.customBlobDocuments;
    const [documentVersion, setDocumentVersion] = useState(0);
    const [isLoaded, setIsLoaded] = useState(false);
    const [model, setModel] = useState(initialModel);

    const providerOptions: { key: Provider; caption: string; icon?: string; }[] = [
        { key: "MxCloudGenAI", caption: "Mendix Cloud GenAI", icon: mendixIconGreyBase64 }
    ]

    useEffect(() => {
        const handleDocumentsChanged = (event: { documents: Array<{ documentId: string }> }) => {
            const { documents } = event;
            if (documents.some(doc => doc.documentId === documentId)) {
                setDocumentVersion(v => v + 1);
            }
        };
        documentApi.addEventListener("documentsChanged", handleDocumentsChanged);
        return () => {
            documentApi.removeEventListener("documentsChanged", handleDocumentsChanged);
        };


    }, []);

    useEffect(() => {
        documentApi
            .getDocumentById<Model>(documentId)
            .then(async (documentFromModel: DocumentLookupResult<Model>) => {
                if (documentFromModel && !("error" in documentFromModel)) {
                    const loadedModel: Model = documentFromModel.document.contents;

                    // Clear keyImportHelper only on the very first load
                    if (!isLoaded && loadedModel.providerFields && 'keyImportHelper' in loadedModel.providerFields) {
                        loadedModel.providerFields.keyImportHelper = '';
                    }

                    setModel({ ...loadedModel });
                    setIsLoaded(true);
                } else {
                    throw new Error(documentFromModel?.error || "Document not found");
                }
            })
            .catch(err => {
                messageBoxApi.show("error", "Error loading document", "Details: " + err?.message || err);
            });
    }, [documentVersion]);

    const changeProvider = useCallback(async (key: Key | null) => {
        handleProviderChange(model, setModel, updateModelDocument(studioPro, documentId), key as Provider)();
    }, [studioPro, model, setModel, documentId]);

    const validateProvider = useCallback(() => {
        if (!model.provider) {
            return "Model provider is required.";
        }
        return undefined;
    }, [model.provider]);

    return (
        <AppThemeProvider studioPro={studioPro}>
            <PageContainer>
                {!isLoaded && <span>Loading document content...</span>}
                {isLoaded && <PageContent>
                    <ContentColumnSmall>
                        <FormDivider label="Common">
                            <ComboBoxWithIcon
                                ariaLabel="Provider"
                                isDisabled={true}
                                label="Provider"
                                selectedKey={model.provider}
                                options={providerOptions}
                                onSelectionChange={changeProvider}
                                validate={validateProvider}
                            />
                        </FormDivider>
                        {model.provider === "MxCloudGenAI" && (
                            <MxCloudGenAI
                                studioPro={studioPro}
                                model={model}
                                setModel={setModel}
                                updateStudioProDocument={updateModelDocument(studioPro, documentId)}
                            />
                        )}
                    </ContentColumnSmall>
                </PageContent>}
            </PageContainer>
        </AppThemeProvider>
    );
};

export const component: IComponent = createDocumentEditorComponent(App);