
import { Model, Provider } from "../../types/model/model";
import { MxCloudGenAIModelFields } from "../../types/model/mxCloudGenAIModel";
import { createNewMxCloudGenAIModelFields } from "../../utils/modelUtils"

export const handleProviderChange = (model: Model, setModel: React.Dispatch<React.SetStateAction<Model>>, updateModelDocument: (model: Model) => Promise<void>, newProvider: Provider) => async () => {

    // Don't reinitialize if provider fields are already of the correct type
    if (model.provider === newProvider && 'key' in model.providerFields) {
        return;
    }

    // Initialize provider-specific fields when provider is selected
    if (newProvider === "MxCloudGenAI") {

        const newProviderFields: MxCloudGenAIModelFields = createNewMxCloudGenAIModelFields();

        const updatedModel = { ...model, provider: newProvider, providerFields: newProviderFields };
        setModel(updatedModel);
        updateModelDocument(updatedModel);
    }
};